--- testFuzzer ---
     1  /*
     2   * testFuzzer.c: Test program for the custom entity loader used to fuzz
     3   * with multiple inputs.
     4   *
     5   * See Copyright for the status of this software.
     6   */
     7
     8  #include <string.h>
     9  #include <libxml/parser.h>
    10  #include <libxml/tree.h>
    11  #include <libxml/xmlstring.h>
    12  #include "fuzz.h"
    13
    14  int
    15  main() {
    16      static const char data[] =
    17          "doc.xml\\\n"
    18          "<!DOCTYPE doc SYSTEM \"doc.dtd\">\n"
    19          "<doc>&ent;</doc>\\\n"
    20          "doc.dtd\\\n"
    21          "<!ELEMENT doc (#PCDATA)>\n"
    22          "<!ENTITY ent SYSTEM \"ent.txt\">\\\n"
    23          "ent.txt\\\n"
    24          "Hello, world!\\\n";
    25      static xmlChar expected[] =
    26          "<?xml version=\"1.0\"?>\n"
    27          "<!DOCTYPE doc SYSTEM \"doc.dtd\">\n"
    28          "<doc>Hello, world!</doc>\n";
    29      const char *docBuffer;
    30      size_t docSize;
    31      xmlDocPtr doc;
    32      xmlChar *out;
    33      int ret = 0;
    34
    35      xmlSetExternalEntityLoader(xmlFuzzEntityLoader);
    36
    37      xmlFuzzDataInit(data, sizeof(data) - 1);
    38      xmlFuzzReadEntities();
    39      docBuffer = xmlFuzzMainEntity(&docSize);
    40      doc = xmlReadMemory(docBuffer, docSize, NULL, NULL,
    41                          XML_PARSE_NOENT | XML_PARSE_DTDLOAD);
    42
    43      xmlDocDumpMemory(doc, &out, NULL);
    44      if (xmlStrcmp(out, expected) != 0) {
    45          fprintf(stderr, "Expected:\n%sGot:\n%s", expected, out);
    46          ret = 1;
    47      }
    48
    49      xmlFree(out);
    50      xmlFreeDoc(doc);
    51      xmlFuzzDataCleanup();
    52
    53      return(ret);
    54  }
